css:
.ea2457-container {
    padding: 24px;
    background-color: #f3f5f7;
    color: #22271f;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    font-size: 15px;
    line-height: 1.5;
}
.ea2457-container * { box-sizing: border-box; }
.ea2457-header { background-color: #1f4a44; color: #f1f6fa; padding: 22px 26px 20px; border-bottom: 4px solid #c0703a; border-radius: 22px 22px 0 0; margin-bottom: 18px; }
.ea2457-eyebrow { font-size: 0.72rem; letter-spacing: 0.14em; text-transform: uppercase; color: #d6e4ee; background-color: #1f4a44; margin-bottom: 6px; }
.ea2457-header h1 { margin: 0; font-size: 1.7rem; font-weight: 700; color: #f1f6fa; background-color: #1f4a44; }
.ea2457-sub { margin: 8px 0 0; color: #e3edf4; background-color: #1f4a44; max-width: 70ch; }
.ea2457-topbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; }
.ea2457-period { font-size: 0.9rem; color: #22271f; background-color: #ffffff; border: 1px solid #cbd4dc; border-radius: 999px; padding: 6px 14px; }
.ea2457-sep { color: #5a5f52; background-color: #ffffff; padding: 0 4px; }
.ea2457-period #roundName { font-weight: 600; }
.ea2457-kpis { display: grid; grid-template-columns: repeat(6, 1fr); gap: 10px; margin-bottom: 18px; }
.ea2457-kpi { background-color: #ffffff; border: 1px solid #cbd4dc; border-radius: 16px; padding: 12px 14px; }
.ea2457-kpi-label { font-size: 0.7rem; letter-spacing: 0.08em; text-transform: uppercase; color: #5a5f52; background-color: #ffffff; min-height: 2.2em; }
.ea2457-kpi-value { font-size: 1.45rem; font-weight: 700; color: #1f4a44; background-color: #ffffff; line-height: 1.1; margin-top: 4px; font-variant-numeric: tabular-nums; transition: color 0.2s ease; }
.ea2457-kpi-score { color: #1f4a44; }
.ea2457-kpi-unit { font-size: 0.72rem; color: #5a5f52; background-color: #ffffff; margin-top: 2px; }
.ea2457-briefing { background-color: #ffffff; border: 1px solid #cbd4dc; border-left: 5px solid #c0703a; border-radius: 0 16px 16px 0; padding: 14px 18px; margin-bottom: 16px; }
.ea2457-box-label { font-size: 0.72rem; letter-spacing: 0.12em; text-transform: uppercase; color: #1f4a44; background-color: #ffffff; font-weight: 700; margin-bottom: 6px; }
.ea2457-briefing-text { color: #22271f; background-color: #ffffff; max-width: 80ch; }
.ea2457-panel { background-color: #ffffff; border: 1px solid #cbd4dc; border-radius: 16px; padding: 18px 20px; margin-bottom: 16px; }
.ea2457-panel h2 { margin: 0 0 6px; font-size: 1.15rem; font-weight: 700; color: #1f4a44; background-color: #ffffff; }
.ea2457-panel-intro { margin: 0 0 14px; color: #3e4438; background-color: #ffffff; max-width: 80ch; }
.ea2457-fields { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.ea2457-field label { display: block; font-size: 0.82rem; font-weight: 600; color: #22271f; background-color: #ffffff; margin-bottom: 4px; }
.ea2457-select { width: 100%; padding: 8px 10px; border: 1px solid #8f927f; border-radius: 10px; background-color: #ffffff; color: #22271f; font-size: 0.9rem; font-family: inherit; }
.ea2457-select option { background-color: #ffffff; color: #22271f; }
.ea2457-select:focus-visible, .ea2457-btn:focus-visible { outline: 3px solid #c0703a; outline-offset: 2px; }
.ea2457-actions { display: flex; justify-content: flex-end; gap: 10px; margin-bottom: 16px; }
.ea2457-btn { border: none; border-radius: 999px; padding: 10px 20px; font-size: 0.92rem; font-weight: 600; cursor: pointer; font-family: inherit; }
.ea2457-btn-primary { background-color: #1f4a44; color: #ffffff; }
.ea2457-btn-secondary { background-color: #e2e8ee; color: #22271f; }
.ea2457-btn:disabled { opacity: 0.55; cursor: not-allowed; }
.ea2457-result, .ea2457-feedback, .ea2457-chart, .ea2457-history { background-color: #ffffff; border: 1px solid #cbd4dc; border-radius: 16px; padding: 14px 18px; margin-bottom: 16px; }
.ea2457-result-text, .ea2457-feedback-text { color: #22271f; background-color: #ffffff; max-width: 90ch; }
.ea2457-feedback-text.ea2457-warn { border-left: 4px solid #8a3b12; padding-left: 10px; }
.ea2457-reveal { display: block; margin-top: 6px; color: #7a3410; background-color: #ffffff; font-weight: 600; }
.ea2457-chart-wrap { position: relative; height: 220px; }
.ea2457-table-wrap { overflow-x: auto; }
.ea2457-table { width: 100%; border-collapse: collapse; font-size: 0.85rem; font-variant-numeric: tabular-nums; }
.ea2457-table th { text-align: left; color: #22271f; background-color: #e4eaef; padding: 6px 8px; border-bottom: 1px solid #cbd4dc; }
.ea2457-table td { color: #22271f; background-color: #ffffff; padding: 6px 8px; border-bottom: 1px solid #e4eaef; }
.ea2457-cm { text-align: center; color: #22271f; background-color: #ffffff; }
.ea2457-cm-score { font-size: 2.6rem; font-weight: 700; color: #1f4a44; background-color: #ffffff; }
.ea2457-cm-max { font-size: 1.1rem; color: #5a5f52; background-color: #ffffff; }
.ea2457-cm-verdict { font-size: 1.15rem; font-weight: 700; color: #22271f; background-color: #ffffff; margin-bottom: 10px; }
.ea2457-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin: 10px 0; }
.ea2457-cm-kpi { font-size: 0.8rem; color: #5a5f52; background-color: #f3f5f7; border-radius: 10px; padding: 8px; }
.ea2457-cm-kpi strong { display: block; font-size: 1.05rem; color: #22271f; background-color: #f3f5f7; }
.ea2457-cm-debrief { text-align: left; color: #22271f; background-color: #ffffff; margin: 10px 0; }
.ea2457-cm-insights { text-align: left; color: #22271f; background-color: #ffffff; }
@media (max-width: 900px) { .ea2457-kpis { grid-template-columns: repeat(2, 1fr); } .ea2457-fields { grid-template-columns: 1fr; } .ea2457-cm-kpis { grid-template-columns: repeat(2, 1fr); } }
@media (prefers-reduced-motion: reduce) { .ea2457-container * { transition: none !important; } }
.ea2457-cases { display: block; margin-top: 8px; color: #22271f; background-color: #ffffff; }
.ea2457-cases span { display: block; color: #22271f; background-color: #ffffff; }

