        var ch = d4.choice, ng = d4.neg, af = d4.after;
        var BW = C.BM * 12.0 / 52.0;
        // diagnosis, complementary skills and visibility
        var D = C.QE[es] * C.QW[wa];
        var K = (C.WK[0] * C.KP[pi] + C.WK[1] * C.KL[le] + C.WK[2] * C.KT[tl]) * (C.KD0 + C.KD1 * D);
        var V = C.VT[tl] * C.VP[pi] * C.VM[te];
        // the cut in your team, the new role and the outside market
        var SL = clamp(C.SL0 - C.SLK * K - C.SLV * V + C.SLN[ng], C.SL_MIN, C.SL_MAX);
        var PR, bA0, rA;
        if (mv === 'apply') { PR = Math.min(C.PR_MAX, C.PR0 + C.PRK * K + C.PRV * V); bA0 = C.A_BASE; rA = C.RA_APPLY; }
        else if (mv === 'elsewhere') { PR = C.PE0 + C.PEV * V; bA0 = C.SAL; rA = C.RA_ELSE * SL; }
        else { PR = C.PW0 + C.PWV * V; bA0 = C.SAL; rA = SL; }
        var Rx = 0.5 * C.OK[ou] + 0.5 * K;
        var PN = C.PN0 + C.PNR * Rx;
        var KPp = C.KEEP[ng], up = C.UP[ng];
        var pA = 0.0, pN = 0.0;
        if (ch === 'role') { pA = PR * KPp; }
        else if (ch === 'leave') { pN = PN * KPp; }
        var pS = 1.0 - pA - pN;
        var bA = bA0 * (1.0 + up), bN = C.N_BASE * (1.0 + up);
        var rN = C.RN0 - C.RNK * K;
        var E = pA * rA + pS * SL + pN * rN;
        var WX = C.WX0 + C.WX1 * (1.0 - Rx);
        var bX = C.BX0 + C.BXK * K;
        var g = C.GF[af];
        var rest = C.HZ - C.TC;
        var lost = function(b) { return b * (C.TC - C.T4) / 52.0 * (1.0 + g) + BW * Math.min(WX, rest) + bX * Math.max(0.0, rest - WX) / 52.0; };
        var kept = function(b) { return b * (C.HZ - C.T4) / 52.0 * (1.0 + g); };
        var base = C.SAL * C.T4 / 52.0;
        var F = base + pA * ((1.0 - rA) * kept(bA) + rA * lost(bA)) + pS * ((1.0 - SL) * kept(C.SAL) + SL * lost(C.SAL)) + pN * ((1.0 - rN) * kept(bN) + rN * lost(bN));
        var fees = C.FL[le] + C.FA[af];
        var H = E * Math.min(WX, rest);
        var xpay = WX < rest ? bX : 0.0;
        var R = (pA * ((1.0 - rA) * bA + rA * xpay) + pS * ((1.0 - SL) * C.SAL + SL * xpay) + pN * ((1.0 - rN) * bN + rN * xpay)) * (1.0 + C.GR[af]);
        var SEVi = C.SAL / 365.0 * C.SEVD * C.YRS;
        var SEV = pA * rA * SEVi + pS * SL * SEVi + pN * rN * bN / 365.0 * C.SEVN;
        var N = clamp(C.N0 + C.NE[es] + C.NW[wa] + C.NT[tl] + C.NP[pi] + C.NL[le] + C.NO[ou] + C.NU[up_] + C.NM[te] + C.NA[af], 0.0, 100.0);
        var pD = 0.0, L = 0.0;
        if (pi === 'hoard') {
            pD = Math.min(C.PD_MAX, C.PD0 + C.PDA * pA + C.PDN * pN + C.PDX * E);
            L = pD * (SEVi + C.SAL * C.HCOST_M / 12.0);
        }
        return {
            F: F - fees, E: E, R: R, N: N, L: L, H: H, D: D, K: K, V: V, SL: SL, PR: PR, PN: PN, pA: pA, pN: pN, pS: pS, WX: WX, bX: bX,
            SEV: SEV, fees: fees, pD: pD, hflag: pi === 'hoard' ? 1.0 : 0.0
        };
    }

    // Your own estimate: the status quo until you update it; the calibration error is its distance from the model.
    function evaluate(dec) {
        var q = core(dec);
        var d1 = dec.round1;
        var d3 = dec.round3;
        var wa = d1.watch;
        var e1, est, e3;
        if (d1.est === 'tasks') { e1 = core({ round1: d1, round2: STATUSQUO.round2, round3: STATUSQUO.round3, round4: STATUSQUO.round4 }).E; }
        else { e1 = C.EST[d1.est]; }
        if (!d3 || d3.update === 'keep') { est = e1; }
        else if (d3.update === 'panic') { est = 1.0; }
        else {
            e3 = core({ round1: d1, round2: dec.round2, round3: d3 }).E;
            est = e3 + (1.0 - C.QW[wa]) * (C.TGT[wa] - e3);
        }
        q.est = est;
        q.CE = Math.abs(est - q.E) * 100.0;
        return q;
    }

    class Veinticuatro2457Adapter extends USF.SimulationAdapter {
        constructor() {
            super();
