            if (d.round2) { set('r2_pilot', d.round2.pilot); set('r2_learn', d.round2.learn); set('r2_out', d.round2.out); }
            if (d.round3) { set('r3_update', d.round3.update); set('r3_move', d.round3.move); set('r3_team', d.round3.team); }
            if (d.round4) { set('r4_choice', d.round4.choice); set('r4_neg', d.round4.neg); set('r4_after', d.round4.after); }
        }

        _t(key, vars) {
