        }

        // Spanish format in es (point thousands, comma decimals); English format in en.
        _fmtNum(v, dec) {
            var n = Number(v) || 0;
            var neg = n < 0;
            var f = Math.abs(n).toFixed(dec);
            var parts = f.split('.');
            var s = parts[0];
            var out = '';
            var th = this._lang() === 'en' ? ',' : '.';
            var dp = this._lang() === 'en' ? '.' : ',';
            while (s.length > 3) { out = th + s.slice(-3) + out; s = s.slice(0, -3); }
            out = s + out;
            if (parts.length > 1) { out = out + dp + parts[1]; }
