                F: this._fmtE(q.F), E: this._fmtPct(q.E, 1), R: this._fmtE(q.R), N: this._fmtN(q.N), est: this._fmtPct(q.est, 1), C: this._fmtP(q.CE)
            });
            html += '<span class="ea2457-cases">' + this._t('s_detail', { d: this._fmtNum(q.D, 2), k: this._fmtNum(q.K, 2), v: this._fmtNum(q.V, 2), sl: this._fmtPct(q.SL, 0), pr: this._fmtPct(q.PR, 0), la: this._fmtPct(q.pA, 0), ln: this._fmtPct(q.pN, 0), h: this._fmtH(q.H), sev: this._fmtE(q.SEV) }) + '</span>';
