        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = sim && sim.state ? sim.state : { currentPeriod: 1, history: [] };
            var period = state.currentPeriod || 1;
            var done = state.history ? state.history.length : 0;
            var warn = function(key) {
                sim.uiManager.showNotification(sim.t(key), 'warning');
                return false;
            };
            if (done >= this.ROUNDS.length || period > this.ROUNDS.length) { return warn('warn_finished'); }
            if (period === 1) {
                var est1 = this._readSelect('r1_est', CTRL.round1.est);
                var watch1 = this._readSelect('r1_watch', CTRL.round1.watch);
                var talk1 = this._readSelect('r1_talk', CTRL.round1.talk);
                if (!est1 || !watch1 || !talk1) { return warn('warn_r1'); }
                decisions.round1 = { est: est1, watch: watch1, talk: talk1 };
                return true;
            }
            if (period === 2) {
                var pilot2 = this._readSelect('r2_pilot', CTRL.round2.pilot);
                var learn2 = this._readSelect('r2_learn', CTRL.round2.learn);
                var out2 = this._readSelect('r2_out', CTRL.round2.out);
                if (!pilot2 || !learn2 || !out2) { return warn('warn_r2'); }
                decisions.round2 = { pilot: pilot2, learn: learn2, out: out2 };
                return true;
            }
            if (period === 3) {
                var update3 = this._readSelect('r3_update', CTRL.round3.update);
                var move3 = this._readSelect('r3_move', CTRL.round3.move);
                var team3 = this._readSelect('r3_team', CTRL.round3.team);
                if (!update3 || !move3 || !team3) { return warn('warn_r3'); }
                decisions.round3 = { update: update3, move: move3, team: team3 };
                return true;
            }
            if (period === 4) {
                var choice4 = this._readSelect('r4_choice', CTRL.round4.choice);
                var neg4 = this._readSelect('r4_neg', CTRL.round4.neg);
                var after4 = this._readSelect('r4_after', CTRL.round4.after);
                if (!choice4 || !neg4 || !after4) { return warn('warn_r4'); }
                decisions.round4 = { choice: choice4, neg: neg4, after: after4 };
                return true;
            }
