        calculateResults(state) {
            var out = this._computeRound(state);
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 400);
            return out;
        }

        // Round model. Every decision is re-evaluated from the decision history, so a resubmit is idempotent.
        _computeRound(state) {
            var ds = state.domainState;
            var raw = state.decisions || {};
            var period = state.currentPeriod || 1;
            var saved = ds.dec || {};
            var d = {};
            var k;
            for (k = 1; k <= period; k++) {
                if (raw['round' + k]) { d['round' + k] = raw['round' + k]; }
                else if (k < period && saved['round' + k]) { d['round' + k] = saved['round' + k]; }
            }
            ds.dec = JSON.parse(JSON.stringify(d));
            var rounds = [];
            var periods = [];
            var total = 0.0;
            var cap = 100.0;
            var r, known, q, rub, W, of, oe, orr, on, oc, pts;
            for (r = 1; r <= period; r++) {
                known = knownUpTo(d, r);
                q = evaluate(known);
                q.t = r;
                rub = this._rubric(known, r);
                W = C.W_OUT[r - 1];
                of = W * C.W_F * clamp((q.F - q.L - C.F_LO) / (C.F_HI - C.F_LO), 0.0, 1.0);
                oe = W * C.W_E * clamp((C.E_HI - q.E) / (C.E_HI - C.E_LO), 0.0, 1.0);
                orr = W * C.W_R * clamp((q.R - C.R_LO) / (C.R_HI - C.R_LO), 0.0, 1.0);
                on = W * C.W_N * clamp((q.N - C.N_LO) / (C.N_HI - C.N_LO), 0.0, 1.0);
                oc = W * C.W_C * clamp((C.C_HI - q.CE) / (C.C_HI - C.C_LO), 0.0, 1.0);
                pts = rub + of + oe + orr + on + oc;
                total += pts;
                cap = 100.0;
                if (q.hflag > 0) { cap = Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAPC_W * q.pD); }
                periods.push(q);
                rounds.push({ period: r, rub: rub, of: of, oe: oe, orr: orr, on: on, oc: oc, pts: pts, verdictKey: this._verdict(known, r) });
            }
            var last = periods[periods.length - 1];
            ds.rounds = rounds;
            ds.periods = periods;
            ds.hoardP = last.hflag > 0 ? last.pD : 0;
            ds.total = total;
            ds.cap = cap;
            var score = this._composite(ds);
            ds.capKeys = [];
            if (last.hflag > 0) { ds.capKeys.push('cap_hoard'); }
            ds.performance = { overallScore: score };
            ds.performanceTier = this._tier(score);
            ds.scoreHistory = (ds.scoreHistory || []).slice(0, period - 1);
            ds.scoreHistory[period - 1] = score;
            ds.scoreHistory.length = period;
            return {
                period: period,
                roundPoints: Math.round(rounds[period - 1].pts * 10) / 10,
                F: Math.round(last.F),
                E: Math.round(last.E * 1000) / 1000,
                R: Math.round(last.R),
                N: Math.round(last.N),
                CE: Math.round(last.CE),
                L: Math.round(last.L),
                score: score,
                overallScore: score
            };
        }

        _rubric(dec, r) {
            var P = C.PTS;
            var d = dec['round' + r];
            var keys = Object.keys(CTRL['round' + r]);
            var s = 0, i;
            for (i = 0; i < keys.length; i++) { s += P[RK[keys[i]]][d[keys[i]]]; }
            return s;
        }

        _verdict(dec, r) {
            var d = dec['round' + r];
            var order = VORDER[r];
            var i;
            for (i = 0; i < order.length; i++) {
                if (d[order[i][0]] === order[i][1]) { return order[i][0] + '_' + order[i][1]; }
            }
            return 'ok';
        }

        _composite(ds) {
            var total = Math.min((ds && typeof ds.cap === 'number') ? ds.cap : 100, (ds && ds.total) || 0);
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

