            return this._t('hint_r' + r.period + '_' + r.verdictKey);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var ps = ds.periods || [];
            var score = this._composite(ds);
            var performance = 'Beginner';
            if (score >= 55) { performance = 'Good'; }
            if (score >= 75) { performance = 'Excellent'; }
            var q = ps.length ? ps[ps.length - 1] : { F: 0, E: 0, R: 0, N: 0, CE: 0, L: 0, hflag: 0 };
            var insights = [];
            insights.push((q.F - q.L) >= C.F_OK ? this._t('insight_f_ok') : this._t('insight_f_bad'));
            insights.push(q.E < C.E_OK ? this._t('insight_e_ok') : this._t('insight_e_bad'));
            insights.push(q.R >= C.R_OK ? this._t('insight_r_ok') : this._t('insight_r_bad'));
            insights.push(q.N >= C.N_OK ? this._t('insight_n_ok') : this._t('insight_n_bad'));
            insights.push(q.CE <= C.C_OK ? this._t('insight_c_ok') : this._t('insight_c_bad'));
            insights.push((q.hflag > 0 || q.L > 0) ? this._t('insight_law_bad') : this._t('insight_law_ok'));
            insights.push(this._t('insight_next'));
            return {
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                F: q.F,
                E: q.E,
                R: q.R,
                N: q.N,
                CE: q.CE,
                L: q.L,
                hoarded: ds.hoardP || 0,
                rounds: (ds.scoreHistory || []).length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ea2457-cm">'
                + '<div class="ea2457-cm-score">' + score + '<span class="ea2457-cm-max">/100</span></div>'
                + '<div class="ea2457-cm-verdict">' + (s.performanceLabel || s.performance || '') + '</div>'
                + '<div class="ea2457-cm-kpis">'
                + '<div class="ea2457-cm-kpi">' + this._t('cm_kpi_f') + '<strong>' + this._fmtE(s.F) + '</strong></div>'
                + '<div class="ea2457-cm-kpi">' + this._t('cm_kpi_e') + '<strong>' + this._fmtPct(s.E, 1) + '</strong></div>'
                + '<div class="ea2457-cm-kpi">' + this._t('cm_kpi_r') + '<strong>' + this._fmtE(s.R) + '</strong></div>'
                + '<div class="ea2457-cm-kpi">' + this._t('cm_kpi_n') + '<strong>' + this._fmtN(s.N) + '</strong></div>'
                + '<div class="ea2457-cm-kpi">' + this._t('cm_kpi_c') + '<strong>' + this._fmtP(s.CE) + '</strong></div>'
                + '<div class="ea2457-cm-kpi">' + this._t('cm_kpi_l') + '<strong>' + this._fmtE(s.L) + '</strong></div>'
                + '</div>'
                + '<div class="ea2457-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ea2457-cm-insights">' + items + '</ul>'
                + '</div>';
        }

